BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE account_status AS ENUM ('pending_verification','active','deactivated','deletion_pending','deleted');
CREATE TYPE visibility AS ENUM ('private','approved_connections','matched_mentors','authorized_organization','explicitly_hidden');
CREATE TYPE organization_kind AS ENUM ('hospital','clinic','community','owner');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, password_hash text NOT NULL, status account_status NOT NULL DEFAULT 'pending_verification', email_verified_at timestamptz, failed_attempts integer NOT NULL DEFAULT 0, locked_until timestamptz, mfa_secret_ciphertext bytea, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE UNIQUE INDEX users_active_email ON users (lower(email)) WHERE deleted_at IS NULL;
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name text, pronouns text, locale text NOT NULL DEFAULT 'en', authorized_representative_user_id uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (code text PRIMARY KEY, privileged boolean NOT NULL);
INSERT INTO roles(code,privileged) VALUES ('patient',false),('survivor',false),('caregiver',false),('peer_mentor',true),('moderator',true),('hospital_coordinator',true),('clinic_coordinator',true),('content_reviewer',true),('pharmacist_reviewer',true),('medical_reviewer',true),('privacy_reviewer',true),('security_reviewer',true),('administrator',true);
CREATE TABLE role_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), role_code text NOT NULL REFERENCES roles(code), approved_by uuid NOT NULL REFERENCES users(id), reason text NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE user_roles (user_id uuid REFERENCES users(id) ON DELETE CASCADE, role_code text REFERENCES roles(code), approval_id uuid REFERENCES role_approvals(id), PRIMARY KEY(user_id,role_code));
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind organization_kind NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_memberships (organization_id uuid REFERENCES organizations(id), user_id uuid REFERENCES users(id), role_code text NOT NULL REFERENCES roles(code), status text NOT NULL CHECK(status IN ('pending','active','revoked')), approved_by uuid REFERENCES users(id), PRIMARY KEY(organization_id,user_id,role_code));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_digest bytea UNIQUE NOT NULL, csrf_digest bytea NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, ip_hash bytea, user_agent_hash bytea, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose text NOT NULL CHECK(purpose IN ('email_verification','password_reset')), token_digest bytea UNIQUE NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE health_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('condition','medication','procedure','treatment','symptom','allergy','supplement','wellness_preference')), label_ciphertext bytea NOT NULL, details_ciphertext bytea, visibility visibility NOT NULL DEFAULT 'private', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE VIEW conditions AS SELECT * FROM health_entries WHERE kind='condition'; CREATE VIEW medications AS SELECT * FROM health_entries WHERE kind='medication'; CREATE VIEW procedures AS SELECT * FROM health_entries WHERE kind='procedure'; CREATE VIEW treatments AS SELECT * FROM health_entries WHERE kind='treatment'; CREATE VIEW symptoms AS SELECT * FROM health_entries WHERE kind='symptom'; CREATE VIEW allergies AS SELECT * FROM health_entries WHERE kind='allergy'; CREATE VIEW supplements AS SELECT * FROM health_entries WHERE kind='supplement'; CREATE VIEW wellness_preferences AS SELECT * FROM health_entries WHERE kind='wellness_preference';
CREATE TABLE match_preferences (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, preferences_ciphertext bytea NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES users(id), mentor_id uuid NOT NULL REFERENCES users(id), status text NOT NULL, approved_at timestamptz, ended_at timestamptz, UNIQUE(patient_id,mentor_id));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_members (conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id), body_ciphertext bytea NOT NULL, sent_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id), initiated_by uuid NOT NULL REFERENCES users(id), provider_reference_ciphertext bytea, started_at timestamptz, ended_at timestamptz);
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), storage_key text UNIQUE NOT NULL, encrypted_data_key bytea NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 26214400), scan_status text NOT NULL DEFAULT 'pending', visibility visibility NOT NULL DEFAULT 'private', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE imported_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), document_id uuid REFERENCES documents(id), source text NOT NULL, payload_ciphertext bytea NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consent_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), purpose text NOT NULL, policy_version text NOT NULL, granted_at timestamptz NOT NULL, withdrawn_at timestamptz, capture_method text NOT NULL, ip_hash bytea);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, actor_id uuid REFERENCES users(id), subject_id uuid REFERENCES users(id), organization_id uuid REFERENCES organizations(id), metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES users(id), subject_user_id uuid REFERENCES users(id), message_id uuid REFERENCES messages(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE blocks (blocker_id uuid REFERENCES users(id), blocked_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
CREATE TABLE moderation_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid REFERENCES reports(id), moderator_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, rationale text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feature_flags (key text NOT NULL, environment text NOT NULL CHECK(environment IN ('development','test','staging','production')), enabled boolean NOT NULL DEFAULT false, rules jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(key,environment));
CREATE TABLE content_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'draft', created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE content_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES content_items(id), reviewer_id uuid NOT NULL REFERENCES users(id), reviewer_role text NOT NULL REFERENCES roles(code), decision text NOT NULL, notes text, reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES content_items(id), citation text NOT NULL, url text, accessed_at date NOT NULL);
CREATE TABLE background_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_error text);
CREATE INDEX audit_subject_time ON audit_events(subject_id,occurred_at DESC); CREATE INDEX jobs_ready ON background_jobs(status,available_at);
ALTER TABLE health_entries ENABLE ROW LEVEL SECURITY; ALTER TABLE messages ENABLE ROW LEVEL SECURITY; ALTER TABLE documents ENABLE ROW LEVEL SECURITY; ALTER TABLE organization_memberships ENABLE ROW LEVEL SECURITY;
-- The API sets app.user_id/app.organization_ids per transaction; the API authorization layer remains mandatory.
CREATE POLICY own_health ON health_entries USING (user_id = nullif(current_setting('app.user_id',true),'')::uuid);
CREATE POLICY conversation_messages ON messages USING (EXISTS (SELECT 1 FROM conversation_members cm WHERE cm.conversation_id=messages.conversation_id AND cm.user_id=nullif(current_setting('app.user_id',true),'')::uuid));
CREATE POLICY own_documents ON documents USING (owner_id=nullif(current_setting('app.user_id',true),'')::uuid);
COMMIT;
